    @staticmethod
    def find_resume(root: str | Path) -> Optional[str]:
        path = Path(root)
        candidates = list(path.glob("ckpt-*.pt")) + list(path.glob("step-*.pt"))
        if not candidates:
            return None
        latest = max(candidates, key=CheckpointManager._extract_step)
        return str(latest)


